<script setup lang="ts">
import { mockApi } from '../api/mock-api';
import { useResource } from '../composables/useResource';
import { usePage } from '../composables/usePage';
import ResourceState from '../components/ResourceState.vue';
import NewsCard from '../components/NewsCard.vue';
const { t, preferences } = usePage();
const { data, loading, error, reload } = useResource(async signal => ({ news: (await mockApi.articles({ signal })).data, drivers: (await mockApi.drivers({ signal })).data }));
</script>
<template><div class="page-heading"><div><p class="eyebrow">{{ t('profile.eyebrow') }}</p><h1 tabindex="-1">{{ t('profile.title') }}</h1><p class="muted">{{ t('profile.description') }}</p></div><RouterLink class="button" to="/settings">{{ t('settings.title') }} ↗</RouterLink></div><div class="guest-panel"><span class="avatar">NR</span><div><h2>{{ t('profile.guest') }}</h2><p class="muted">{{ t('profile.local') }}</p></div></div><ResourceState :loading="loading" :error="error" @retry="reload"><template v-if="data"><section><div class="section-heading"><h2>{{ t('profile.following') }}</h2><span class="caption">{{ preferences.followedDriverIds.length }}</span></div><div v-if="preferences.followedDriverIds.length" class="podium-grid"><RouterLink v-for="driver in data.drivers.filter(item => preferences.followedDriverIds.includes(item.id))" :key="driver.id" class="podium-card" :class="driver.color" :to="`/drivers/${driver.id}`"><span class="avatar small">{{ driver.initials }}</span><div><strong>{{ driver.name }}</strong><p class="caption">{{ driver.team }}</p></div><span>↗</span></RouterLink></div><div v-else class="empty-inline"><p>{{ t('profile.noFollowing') }}</p><RouterLink to="/stats">{{ t('profile.exploreDrivers') }} →</RouterLink></div></section><section><div class="section-heading"><h2>{{ t('profile.saved') }}</h2><span class="caption">{{ preferences.savedArticleIds.length }}</span></div><div v-if="preferences.savedArticleIds.length" class="news-grid"><NewsCard v-for="article in data.news.filter(item => preferences.savedArticleIds.includes(item.id))" :key="article.id" :article="article"/></div><div v-else class="empty-inline"><p>{{ t('profile.noSaved') }}</p><RouterLink to="/news">{{ t('profile.exploreNews') }} →</RouterLink></div></section></template></ResourceState></template>
